    fun labelExpense(): String = if (isIndonesian()) "Pengeluaran" else "Expense"
    fun labelSavings(): String = if (isIndonesian()) "Tabungan" else "Savings"
    fun labelBalance(): String = if (isIndonesian()) "Saldo" else "Balance"
    fun labelCashFlow(): String = if (isIndonesian()) "Arus Kas" else "Cash Flow"
    fun labelBudget(): String = if (isIndonesian()) "Anggaran" else "Budget"
    fun labelGoal(): String = if (isIndonesian()) "Tujuan" else "Goal"
    fun labelRecurring(): String = if (isIndonesian()) "Berulang" else "Recurring"
    fun labelInstallment(): String = if (isIndonesian()) "Cicilan" else "Installment"
    fun labelAllocation(): String = if (isIndonesian()) "Alokasi" else "Allocation"
    fun labelAverage(): String = if (isIndonesian()) "Rata-rata" else "Average"
    fun labelMaximum(): String = if (isIndonesian()) "Maksimum" else "Maximum"
    fun labelMinimum(): String = if (isIndonesian()) "Minimum" else "Minimum"
    fun labelHighest(): String = if (isIndonesian()) "Tertinggi" else "Highest"
    fun labelLowest(): String = if (isIndonesian()) "Terendah" else "Lowest"
    fun labelDaily(): String = if (isIndonesian()) "Harian" else "Daily"
    fun labelWeekly(): String = if (isIndonesian()) "Mingguan" else "Weekly"
    fun labelMonthly(): String = if (isIndonesian()) "Bulanan" else "Monthly"
    fun labelYearly(): String = if (isIndonesian()) "Tahunan" else "Yearly"
}
